#!/usr/bin/env python3
"""Recreate additive population metadata; never creates verification receipts."""
from pathlib import Path
import json,yaml
R=Path(__file__).resolve().parents[4]
source=dict(id='BR2026v2',title='Rational Fourier certificates for prime gaps, explicit intervals, and arithmetic progressions',authors=['Rafael Blanquer Robles'],type='paper',relationship='adapts',url='https://zenodo.org/records/24429650',note='Version2: Lemma5 (§2.1, eq:pair) and Proposition6 (§3, eq:uniform-count); the q=1 proof case and following moduli1/2 paragraph justify ordinary RH rather than full GRH for this specialization.')
def edge(n,c):return dict(node=n,conclusion=c)
def base(f,kind,description):return dict(version='v0.4',node=dict(id=f+'.v1',family=f,version='v1',kind=kind,status='active' if f=='BRFourierInput' else 'awaiting-verification'),project=dict(name=f+'.v1',description=description,authors=['OpenAI (Codex)'],license='Apache-2.0',responsible_maintainers=['hschae']),repository=dict(role='substantive-development'),classification=dict(arxiv=['math.NT'],msc2020=['11N05','11M26']),conclusions=[],sources=[source])
def conclusion(f,c,inputs,just):return dict(id=c,declaration=f+'.v1.'+c,challenge=f+'.v1.challenge_'+c,imports=inputs,imports_status='identified' if inputs else 'none',justifications=[just],designated=just['id'])
node=base('BRFourierInput','paper','The literal finite-affine Fourier norm identity and ordinary-RH q=1 population source specialization, with the source remainder and attained maximum explicit; no numerical answer is a source premise.')
for c,loc,note in [('norm_identity','Lemma5, §2.1, eq:pair','General norm identity on the literal support-five finite mesh; shorter exact witnesses are zero-padded by proved identities.'),('uniform_population_q1','Proposition6, §3, eq:uniform-count; its q=1 proof case and following moduli1/2 paragraph','Ordinary-RH specialization derived from the proof for the principal conductor-one character, not an implication from RH to GRH. The O(F,c) remainder remains an eventual nonnegative-constant bound.')]:
 node['conclusions'].append(conclusion('BRFourierInput',c,[],dict(id='primary-source',kind='literature',source='BR2026v2',locator=loc,note=note)))
node['limitations']=['These analytic propositions remain explicitly literature-backed inputs, not Lean-proved analytic theorems.','The language fragment is the published support-five finite-affine construction, not arbitrary Fourier pairs.','No fixed numerical result, explicit onset, optimality or official Comparator approval is imported.']
(R/'IEANTN/Nodes/BRFourierInput/v1/formalization.yaml').write_text(yaml.safe_dump(node,sort_keys=False,allow_unicode=True))
local=dict(id='local-source-first-proof',kind='lean-noncompliant',note='Completed development Lean proof with only propext, Classical.choice and Quot.sound. Exact input Tables agree definitionally with the actual C source models; source syntax, execution, overflow, sine error and periodic norm outputs are consumed by the witness proof. Full source-only replay is recorded separately. Official Comparator receipt is absent.')
node=base('AffineFourierPrograms','computation','Two distinct actual source-first C program instances, with exact source-model input tables, numerical L1 caps, genuine Fourier witnesses, exact positive leakage, normalization and attained maxima.')
for c in ['sparse_witness','flat_witness']:node['conclusions'].append(conclusion('AffineFourierPrograms',c,[edge('BRFourierInput.v1','norm_identity')],local))
node['limitations']=['The norm identity is the explicit general BRFourierInput.v1 literature premise; actual Fourier correspondence, eligibility, normalization, leakage and maxima are Lean proved.','Source-first PV trusts the pinned Lean kernel and declared compiler, runtime, OS/API and hardware boundary; it does not claim a verified compiler or physical hardware.','The flat source input has origin value15*533333333333333333/(8*10^18), slightly below1; it is not replaced by1.','Matched kernel-only numerical controls prove the same mathematical caps, so this evidence establishes source provenance rather than a causal mathematical advantage of PV.','Official Comparator approval and any explicit ANT onset are absent.']
(R/'IEANTN/Nodes/AffineFourierPrograms/v1/formalization.yaml').write_text(yaml.safe_dump(node,sort_keys=False,allow_unicode=True))
local2=dict(id='local-kernel-consumer',kind='lean-noncompliant',note='Completed development Lean consumer with only standard axioms. The numerical witness, q=1 source theorem and RH are explicit inputs. Source-first and matched kernel-only providers share this same consumer. A complete typed/value dependency audit and cold source replay are recorded separately; official Comparator receipt is absent.')
node=base('RHWeightedPopulation','pipeline','Two ordinary-RH eventual actual-prime population curves and their minimum, improving the previous octic leading-width frontier on the common asymptotic comparison domain without transferring the old explicit onset.')
for c,w in [('sparse_curve','sparse_witness'),('flat_curve','flat_witness')]:node['conclusions'].append(conclusion('RHWeightedPopulation',c,[edge('BRFourierInput.v1','uniform_population_q1'),edge('RH.v1','hypothesis'),edge('AffineFourierPrograms.v1',w)],local2))
for c,inputs in [('frontier_curve',['sparse_curve','flat_curve']),('frontier_count',['frontier_curve']),('one_population',['sparse_curve']),('ten_population',['flat_curve']),('below_octic_leading_frontier',[])]:node['conclusions'].append(conclusion('RHWeightedPopulation',c,[edge('RHWeightedPopulation.v1',x)for x in inputs],local2))
node['limitations']=['Every new population/count conclusion is eventual, with a positive GoodCoefficient margin; no explicit onset or uniform threshold in alpha is claimed.','PrimeInterval.v4.optimized_strict_family has onsetexp24, strict endpoints and1.03<=c<=16. Only its exact asymptotic leading width (9/8)*(alpha+18203/20000) is compared; those stronger finite-domain features are preserved in the old node.','The minimum improves that octic leading line for all nonnegative alpha, but is not a global optimum: the separate new Gaussian gap coefficient is smaller at alpha0.','The analytic BR norm identity and q=1 uniform population proposition remain declared literature inputs, with ordinary RH supplied separately.','No overall PV causal discovery advantage, official Comparator approval, or new unrestricted RH-only analytic theorem is claimed.']
(R/'IEANTN/Nodes/RHWeightedPopulation/v1/formalization.yaml').write_text(yaml.safe_dump(node,sort_keys=False,allow_unicode=True))
for f,imports,theorems in [('AffineFourierPrograms','AffineProgramsSolution',['sparse_witness','flat_witness']),('RHWeightedPopulation','WeightedPopulationSolution',['sparse_curve','flat_curve','frontier_curve','frontier_count','one_population','ten_population','below_octic_leading_frontier'])]:
 p=R/'Solutions'/(f+'.v1');p.mkdir(exist_ok=True)
 (p/'Solution.lean').write_text('/-\nCopyright (c) 2026 IEANTN contributors. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: OpenAI (Codex)\n-/\nimport '+imports+'\n')
 (p/'lakefile.toml').write_text('name = "solution_'+f+'_v1"\nmoreLeanArgs = ["-j1"]\ndefaultTargets = ["Solution"]\n\n[[require]]\nname = "RH080Next"\npath = "../RH080Next.v1"\n\n[[lean_lib]]\nname = "Solution"\nroots = ["Solution"]\n')
 (p/'lean-toolchain').write_bytes((R/'lean-toolchain').read_bytes())
 (p/'comparator.json').write_text(json.dumps(dict(challenge_module='IEANTN.Nodes.'+f+'.v1.Challenge',solution_module='Solution',theorem_names=[f+'.v1.challenge_'+c for c in theorems],permitted_axioms=['propext','Quot.sound','Classical.choice'],enable_nanoda=True),indent=2)+'\n')
 (p/'README.md').write_text('# '+f+'.v1\n\nAdditive canonical population experiment. The exact inputs and two literature predicates are explicit in the node declarations. See ../RH080Next.v1/primal/population/README.md for source-first versus matched kernel-only verification, reproducibility and trust limits. Official Comparator approval is absent.\n')
